            {activeTask && (
              <span className="font-mono text-xs font-semibold text-text-muted group-hover:text-primary transition-colors shrink-0 hidden md:inline">
                {formatTaskKey(activeTask.id)}
              </span>
            )}
          </button>
        </InfoTooltip>
      </div>
    </div>
  );
}
